"use strict";
const marks = /[\u0300-\u036f\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]/g;
const stripMarks = (value) => value.normalize("NFD").replace(marks, "").toLocaleLowerCase();
const referenceRanges = (text, phrase) => {
    let normalized = "";
    const offsets = [];
    let offset = 0;
    for (const character of text) {
        const clean = stripMarks(character);
        normalized += clean;
        for (let index = 0; index < clean.length; index += 1)
            offsets.push(offset);
        offset += character.length;
    }
    const needle = stripMarks(phrase.trim());
    if (!needle)
        return [];
    const matches = [];
    const word = /[\p{L}\p{N}_]/u;
    let start = 0;
    while ((start = normalized.indexOf(needle, start)) >= 0) {
        const end = start + needle.length;
        const bounded = (!word.test(needle[0]) || !word.test(normalized[start - 1] ?? "")) &&
            (!word.test(needle.at(-1) ?? "") || !word.test(normalized[end] ?? ""));
        if (bounded)
            matches.push({ start: offsets[start] ?? 0, end: offsets[end] ?? text.length });
        start = end;
    }
    return matches;
};
const inks = [
    "#f2c867",
    "#efa862",
    "#e89991",
    "#d184a5",
    "#bba4d9",
    "#9fc8dd",
    "#8fc9c2",
    "#b4cfa2",
];
function annotationRuns(text, line, chapter, annotations) {
    const ranges = annotations
        .flatMap((annotation) => {
        const direct = annotation.chapterId === chapter.id
            ? annotation.ranges
                .filter((range) => range.line === line)
                .map((range) => ({ ...range, annotation }))
            : [];
        if (!annotation.reference || !annotation.text)
            return direct;
        const found = referenceRanges(text, annotation.text).map((range) => ({
            line,
            ...range,
            annotation,
        }));
        return [...direct, ...found];
    })
        .sort((a, b) => a.start - b.start || b.end - a.end);
    let cursor = 0;
    const result = [];
    ranges.forEach(({ start: rawStart, end: rawEnd, annotation }) => {
        const start = Math.max(cursor, Math.min(text.length, rawStart));
        const end = Math.max(start, Math.min(text.length, rawEnd));
        if (end > start)
            result.push({ start, end, id: annotation.id, color: annotation.color, density: annotation.density });
        cursor = end;
    });
    return result;
}
function harborEBookAnnotations(raw) {
    const input = JSON.parse(raw);
    if (input.operation === "inks")
        return JSON.stringify(inks);
    const text = input.text ?? "", line = input.line ?? 0, chapter = { id: input.chapterId }, annotations = input.annotations ?? [];
    if (input.operation === "reference")
        return JSON.stringify(referenceRanges(text, input.phrase ?? ""));
    if (input.operation === "chapter")
        return JSON.stringify(input.paragraphs.map(p => ({ line: p.line, runs: annotationRuns(p.text, p.line, chapter, annotations) })).filter(p => p.runs.length));
    return JSON.stringify(annotationRuns(text, line, chapter, annotations));
}
